```vue src/components/windowManager/AppWindow.vue
<script setup>
import Iframe from '../Iframe.vue'
</script>

<template>
  <div class="w-full h-full" :class="loaded ? '' : 'opacity-0'">
    <Iframe
      ref="iframe"
      class="w-full h-full"
      :key="theApp.path"
      :url="currentUrl"
      @loaded="onLoaded"
      @navigated="onNavigated"
    />
  </div>
</template>

<script>
export default {
  name: "AppWindow",
  props: ['app', 'params'],
  data() {
    return {
      loaded: false,
      // URL bound to the iframe `src` (only resolved when the window is created)
      currentUrl: null,
      // Last URL reported by the iframe, used only to persist navigation
      lastUrl: null
    }
  },
  created() {
    const app = this.theApp
    // Restore last navigated URL from params or fall back to app path
    this.currentUrl = this.params?.params?.lastUrl || app?.path
    this.lastUrl = this.currentUrl
    this.loaded = app?.is_vnc
  },
  computed: {
    theApp() {
      // Prefer the explicit prop, then the workspace payload (name + path +
      // metadata), then the app definition and the legacy params slot.
      return this.app ||
        this.params?.params?.workspace ||
        this.params?.params?.app ||
        this.params?.app
    },
    tabId() {
      return this.theApp?.tabId
    }
  },
  methods: {
    onLoaded() {
      this.loaded = true
      // Read the actual current URL and title from the iframe after load
      this.readIframeUrl()
      this.$emit('loaded')
    },
    // Read URL and title directly from iframe contentWindow after navigation
    readIframeUrl() {
      try {
        const iframeEl = this.$refs.iframe?.$el || this.$refs.iframe
        const contentWindow = iframeEl?.contentWindow
        const url = contentWindow?.location?.href
        const title = contentWindow?.document?.title
        if (url && url !== 'about:blank') {
          this.onNavigated(url, title)
        }
      } catch (e) {
        // Cross-origin access blocked, silently ignore
      }
    },
    // Track url changes and persist them in the app params via store
    onNavigated(url, title) {
      if (!url || url === this.lastUrl) return
      // Keep the iframe `src` untouched so in-app navigation doesn't reload it;
      // only remember the url so it can be persisted and restored.
      this.lastUrl = url
      this.persistUrl(url, title)
    },
    // Persist current URL and page title so layout restore can recover them
    persistUrl(url, title) {
      if (!this.tabId) return
      const params = { lastUrl: url }
      // Only store title if it's a non-empty valid string
      if (title && title.trim()) {
        params.title = title.trim()
      }
      this.$storex.ui.updateAppParams({
        tabId: this.tabId,
        params
      })
    }
  }
}
</script>
```

| File Path | Action | Component / Section | Change Description |
| :--- | :--- | :--- | :--- |
| `src/components/windowManager/AppWindow.vue` | Modify | `data` | Add `lastUrl` to track the navigated url independently of the `src`-bound `currentUrl` |
| `src/components/windowManager/AppWindow.vue` | Modify | `created` | Seed `lastUrl` from the restored/initial url |
| `src/components/windowManager/AppWindow.vue` | Modify | `onNavigated` | Dedup and update `lastUrl` (not `currentUrl`) so the iframe is never reloaded by tracking |

### Why this works end-to-end
1. `Iframe` now emits `navigated` on load **and** on in-app (SPA) url changes (1s poll), so the *last visited* url is always known.
2. `AppWindow.onNavigated` stores it in `lastUrl` and calls `persistUrl` → `ui.updateAppParams({ tabId, params: { lastUrl } })`.
3. `updateAppParams` merges into `openApps[tabId].params`, syncs the dockview `panel.params`, and calls `views.onLayoutChanged()` which writes the layout to `localStorage`.
4. On next creation, the saved layout restores `panel.params.lastUrl`, and `AppWindow.created()` sets `currentUrl = lastUrl` → the iframe opens on the last visited page.
5. Because the `src` binding is no longer mutated during navigation, the app is **not** reloaded on every route change.

**Note on cross-origin apps:** for frames on a different origin (`contentWindow` access throws), tracking stops silently and restore falls back to `app.path` — the same behavior as before.

